package controller;
import model.User;import model.Car;import dao.CarDAO;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;
@WebServlet("/cart") public class CartServlet extends HttpServlet{private List<Integer> cart(HttpSession h){Object o=h.getAttribute("carCart");if(o instanceof List)return (List<Integer>)o;List<Integer> l=new ArrayList<>();h.setAttribute("carCart",l);return l;}protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException,ServletException{HttpSession h=q.getSession(false);User u=h==null?null:(User)h.getAttribute("user");if(u==null){s.sendRedirect("login.jsp");return;}List<Integer> l=cart(h);String a=q.getParameter("action");try{if("add".equals(a)){int id=Integer.parseInt(q.getParameter("carId"));Car c=new CarDAO().getCarById(id);if(c!=null&&"Available".equalsIgnoreCase(c.getStatus())&&!l.contains(id))l.add(id);}else if("remove".equals(a))l.remove(Integer.valueOf(Integer.parseInt(q.getParameter("carId"))));}catch(Exception ignored){}List<Car> cars=new ArrayList<>();for(Integer id:new ArrayList<>(l)){Car c=new CarDAO().getCarById(id);if(c==null||!"Available".equalsIgnoreCase(c.getStatus()))l.remove(id);else cars.add(c);}q.setAttribute("cartCars",cars);q.getRequestDispatcher("cart.jsp").forward(q,s);}}
